#!/bin/bash
set -e
echo 'Unpacking...'
cat << 'EOF' | base64 -d | tar -xzf - -C /var/www/snapcut

EOF
echo 'Fixing permissions...'
chown -R azureuser:azureuser /var/www/snapcut
chmod -R 755 /var/www/snapcut/public
echo 'Restarting PM2 snapcut...'
pm2 reload snapcut || pm2 restart snapcut
echo 'DEPLOYMENT_SUCCESSFUL'
